{"content":"import { useState } from 'react';

/**
 * Root component for the 3D 8-Ball Pool Game.
 *
 * Architecture:
 *   App
 *   ├── Scene (R3F Canvas) — to be added in Phase 3
 *   │   ├── PhysicsWorld — to be added in Phase 4
 *   │   ├── Table — to be added in Phase 3
 *   │   ├── Balls — to be added in Phase 3
 *   │   ├── CueStick — to be added in Phase 6
 *   │   └── AimLine — to be added in Phase 6
 *   └── GameUI (HTML overlay) — to be added in Phase 7
 */
function App() {
  const [ready] = useState(true);

  return (
    <div
      style={{
        width: '100vw',
        height: '100vh',
        background: '#1a1a2e',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        fontFamily: 'system-ui, -apple-system, sans-serif',
      }}
    >
      {ready ? (
        <div style={{ textAlign: 'center', color: '#e0e0e0' }}>
          <h1 style={{ fontSize: '2rem', marginBottom: '0.5rem' }}>
            🎱 8-Ball Pool
          </h1>
          <p style={{ color: '#888', fontSize: '0.9rem' }}>
            Project scaffolded — components will be added in upcoming phases.
          </p>
        </div>
      ) : null}
    </div>
  );
}

export default App;","end_line":44,"start_line":0,"total_lines":45}

{"content":"import { Canvas } from '@react-three/fiber';
import { OrbitControls } from '@react-three/drei';
import Table from './Table';
import Balls from './Balls';
import PhysicsWorld from '../physics/PhysicsWorld';
import CueStick from './CueStick';
import AimLine from './AimLine';
import { CAMERA_DEFAULT_POSITION, CAMERA_FOV } from '../constants/table';
import useShotSequence from '../hooks/useShotSequence';
import useSettleDetector from '../hooks/useSettleDetector';

export default function Scene() {
  return (
    <Canvas
      shadows
      camera={{
        position: CAMERA_DEFAULT_POSITION,
        fov: CAMERA_FOV,
        near: 0.1,
        far: 50,
      }}
      style={{ width: '100%', height: '100%' }}
    >
      <color attach="background" args={['#1a1a2e']} />
      <fog attach="fog" args={['#1a1a2e', 5, 15]} />

      {/* Lighting */}
      <ambientLight intensity={0.3} />
      <directionalLight
        position={[0, 3, 0]}
        intensity={1.2}
        castShadow
        shadow-mapSize-width={2048}
        shadow-mapSize-height={2048}
        shadow-camera-far={10}
        shadow-camera-left={-2}
        shadow-camera-right={2}
        shadow-camera-top={2}
        shadow-camera-bottom={-2}
      />
      <pointLight position={[-0.5, 2, -0.8]} intensity={0.4} color="#fff5e6" />
      <pointLight position={[0.5, 2, 0.8]} intensity={0.4} color="#fff5e6" />

      <PhysicsWorld>
        <Table />
        <Balls />
        <CueStick />
        <AimLine />
        <GameHooks />
      </PhysicsWorld>

      <OrbitControls
        enablePan={false}
        minPolarAngle={0.2}
        maxPolarAngle={Math.PI / 2.2}
        minDistance={1}
        maxDistance={5}
        target={[0, 0, 0]}
      />

      {/* Floor */}
      <mesh
        rotation={[-Math.PI / 2, 0, 0]}
        position={[0, -0.8, 0]}
        receiveShadow
      >
        <planeGeometry args={[20, 20]} />
        <meshStandardMaterial color="#1a0f0a" />
      </mesh>
    </Canvas>
  );
}

/**
 * Wrapper component for hooks that need to be inside the Canvas/Physics context
 */
function GameHooks() {
  useSettleDetector();
  useShotSequence();
  return null;
}","end_line":80,"start_line":0,"total_lines":81}

