import type { Vec3Tuple } from '../types';

// Table dimensions (meters)
export const TABLE_LENGTH = 2.24; // Z-axis (long dimension)
export const TABLE_WIDTH = 1.12;  // X-axis (short dimension)
export const TABLE_HEIGHT = 0.02; // Y-axis thickness of bed

// Rail dimensions
export const RAIL_HEIGHT = 0.05;
export const RAIL_WIDTH = 0.06;

// Ball
export const BALL_RADIUS = 0.0285;

// Pocket
export const POCKET_RADIUS = 0.047;

// Playing bounds (half extents)
export const HALF_LENGTH = TABLE_LENGTH / 2;
export const HALF_WIDTH = TABLE_WIDTH / 2;

// Playing surface bounds (where balls can travel, accounting for rail thickness)
export const CUSHION_THICKNESS = 0.03;
export const PLAYING_BOUNDS = {
  minX: -(HALF_WIDTH - CUSHION_THICKNESS),
  maxX: HALF_WIDTH - CUSHION_THICKNESS,
  minZ: -(HALF_LENGTH - CUSHION_THICKNESS),
  maxZ: HALF_LENGTH - CUSHION_THICKNESS,
};

// Head string: 1/4 of table length from head rail
// This is the line behind which the cue ball is placed for the break
export const HEAD_STRING_Z = -HALF_LENGTH / 2;

// Foot spot: center of the foot end (for racking)
// Located at the intersection of the long center line and a line drawn
// through the foot rail's center spot
export const FOOT_SPOT: Vec3Tuple = [0, 0, HALF_LENGTH / 2];

// Pocket center positions (6 pockets)
// 4 corner pockets + 2 side (middle) pockets
export const POCKET_POSITIONS: Vec3Tuple[] = [
  // Corner pockets
  [-HALF_WIDTH, 0, -HALF_LENGTH],  // head-left
  [HALF_WIDTH, 0, -HALF_LENGTH],   // head-right
  [-HALF_WIDTH, 0, HALF_LENGTH],   // foot-left
  [HALF_WIDTH, 0, HALF_LENGTH],    // foot-right
  // Side pockets (middle of long rails)
  [-HALF_WIDTH, 0, 0],             // mid-left
  [HALF_WIDTH, 0, 0],              // mid-right
];

// Pocket labels for readability
export const POCKET_LABELS = [
  'head-left',
  'head-right',
  'foot-left',
  'foot-right',
  'mid-left',
  'mid-right',
] as const;

// Cushion height (how tall the cushion is above the bed)
export const CUSHION_HEIGHT = BALL_RADIUS * 1.5;

// Floor
export const FLOOR_Y = -0.8;

// Camera defaults
export const CAMERA_DEFAULT_POSITION: Vec3Tuple = [0, 1.8, 1.6];
export const CAMERA_FOV = 45;

import type { BallId, Vec3Tuple } from '../types';
import { BALL_RADIUS, HALF_LENGTH, FOOT_SPOT_Z } from './table';

// ─────────────────────────────────────────────────────────────────────────────
// 16 ball colors (standard 8-ball palette)
// ─────────────────────────────────────────────────────────────────────────────
export const BALL_COLORS: Record<BallId, string> = {
  0: '#FFFFFF',  // Cue ball
  1: '#FFD700',  // Yellow (solid)
  2: '#0000FF',  // Blue (solid)
  3: '#FF0000',  // Red (solid)
  4: '#800080',  // Purple (solid)
  5: '#FF8C00',  // Orange (solid)
  6: '#006400',  // Green (solid)
  7: '#8B0000',  // Maroon (solid)
  8: '#000000',  // Eight ball (black)
  9: '#FFD700',  // Yellow (stripe)
  10: '#0000FF', // Blue (stripe)
  11: '#FF0000', // Red (stripe)
  12: '#800080', // Purple (stripe)
  13: '#FF8C00', // Orange (stripe)
  14: '#006400', // Green (stripe)
  15: '#8B0000', // Maroon (stripe)
};

// ─────────────────────────────────────────────────────────────────────────────
// Helpers – ball classification
// ─────────────────────────────────────────────────────────────────────────────
/** Balls 1-7 are solids */
export function isSolid(id: BallId): boolean {
  return id >= 1 && id <= 7;
}

/** Balls 9-15 are stripes */
export function isStripe(id: BallId): boolean {
  return id >= 9 && id <= 15;
}

/** Ball 8 is the eight ball */
export function isEightBall(id: BallId): boolean {
  return id === 8;
}

/** Ball 0 is the cue ball */
export function isCueBall(id: BallId): boolean {
  return id === 0;
}

// ─────────────────────────────────────────────────────────────────────────────
// Standard 8-ball rack layout (triangle at foot spot)
//
// Row 0 (apex):  1 ball   →   solid
// Row 1:         2 balls  →   stripe, solid
// Row 2:         3 balls  →   solid, EIGHT, stripe
// Row 3:         4 balls  →   mixed
// Row 4 (base):  5 balls  →   corners: one solid + one stripe
// ─────────────────────────────────────────────────────────────────────────────
const RACK_ORDER: BallId[] = [
  // row 0
  1,
  // row 1
  9, 2,
  // row 2 (8-ball in centre)
  10, 8, 11,
  // row 3
  3, 14, 6, 15,
  // row 4 (corners: solid + stripe)
  4, 12, 7, 13, 5,
];

/**
 * Returns the 16 ball starting positions as `[x, y, z]` tuples.
 *
 * The apex ball sits on the foot spot; each subsequent row is offset along
 * the Z-axis by `BALL_RADIUS * 2 * cos(30°)`.  Columns within a row are
 * centred around X = 0 with `BALL_RADIUS * 2` spacing.
 */
export function getRackPositions(): Record<BallId, Vec3Tuple> {
  const positions: Record<number, Vec3Tuple> = {};
  const diameter = BALL_RADIUS * 2;
  const spacing = diameter * 1.02; // tiny gap to avoid initial overlap
  const rowDepth = spacing * Math.cos(Math.PI / 6); // cos(30°) ≈ 0.866

  let idx = 0;
  for (let row = 0; row < 5; row++) {
    const count = row + 1;
    const z = FOOT_SPOT_Z + row * rowDepth;
    for (let col = 0; col < count; col++) {
      const x = (col - (count - 1) / 2) * spacing;
      positions[RACK_ORDER[idx]] = [x, BALL_RADIUS, z];
      idx++;
    }
  }

  // Cue ball behind the head string (~40 % from head rail)
  positions[0] = [0, BALL_RADIUS, -HALF_LENGTH * 0.4];

  return positions as Record<BallId, Vec3Tuple>;
}

/** Convenience: look up a ball's hex colour string */
export function getBallColor(id: BallId): string {
  return BALL_COLORS[id];
}

/**
 * 3D vector utilities operating on [x, y, z] tuples.
 *
 * These pure functions avoid allocating class instances and are
 * compatible with Three.js, cannon-es, and our own constants.
 */
export type Vec3Tuple = [number, number, number];

// ---------------------------------------------------------------------------
// Creation / conversion helpers
// ---------------------------------------------------------------------------

/** Create a Vec3Tuple from individual components. */
export function vec3(x: number, y: number, z: number): Vec3Tuple {
  return [x, y, z];
}

/** Zero vector constant (immutable – treat as read-only). */
export const VEC3_ZERO: Readonly<Vec3Tuple> = [0, 0, 0];

/** Unit vectors along each axis. */
export const VEC3_UP: Readonly<Vec3Tuple> = [0, 1, 0];
export const VEC3_RIGHT: Readonly<Vec3Tuple> = [1, 0, 0];
export const VEC3_FORWARD: Readonly<Vec3Tuple> = [0, 0, 1];

// ---------------------------------------------------------------------------
// Basic operations
// ---------------------------------------------------------------------------

/** Euclidean distance between two points. */
export function distance(a: Vec3Tuple, b: Vec3Tuple): number {
  const dx = a[0] - b[0];
  const dy = a[1] - b[1];
  const dz = a[2] - b[2];
  return Math.sqrt(dx * dx + dy * dy + dz * dz);
}

/** Squared distance (avoids the sqrt when only comparisons are needed). */
export function distanceSq(a: Vec3Tuple, b: Vec3Tuple): number {
  const dx = a[0] - b[0];
  const dy = a[1] - b[1];
  const dz = a[2] - b[2];
  return dx * dx + dy * dy + dz * dz;
}

/** Length (magnitude) of a vector. */
export function length(v: Vec3Tuple): number {
  return Math.sqrt(v[0] * v[0] + v[1] * v[1] + v[2] * v[2]);
}

/** Squared length. */
export function lengthSq(v: Vec3Tuple): number {
  return v[0] * v[0] + v[1] * v[1] + v[2] * v[2];
}

/** Return the unit-length copy of `v`. Returns [0,0,0] for zero-length input. */
export function normalize(v: Vec3Tuple): Vec3Tuple {
  const len = Math.sqrt(v[0] * v[0] + v[1] * v[1] + v[2] * v[2]);
  if (len === 0) return [0, 0, 0];
  return [v[0] / len, v[1] / len, v[2] / len];
}

/** Component-wise subtraction: a − b. */
export function sub(a: Vec3Tuple, b: Vec3Tuple): Vec3Tuple {
  return [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
}

/** Component-wise addition: a + b. */
export function add(a: Vec3Tuple, b: Vec3Tuple): Vec3Tuple {
  return [a[0] + b[0], a[1] + b[1], a[2] + b[2]];
}

/** Scalar multiplication. */
export function scale(v: Vec3Tuple, s: number): Vec3Tuple {
  return [v[0] * s, v[1] * s, v[2] * s];
}

/** Negate a vector. */
export function negate(v: Vec3Tuple): Vec3Tuple {
  return [-v[0], -v[1], -v[2]];
}

/** Component-wise multiplication (Hadamard product). */
export function multiply(a: Vec3Tuple, b: Vec3Tuple): Vec3Tuple {
  return [a[0] * b[0], a[1] * b[1], a[2] * b[2]];
}

// ---------------------------------------------------------------------------
// Interpolation / reflection
// ---------------------------------------------------------------------------

/** Linear interpolation between `a` and `b` by factor `t` ∈ [0, 1]. */
export function lerp(a: Vec3Tuple, b: Vec3Tuple, t: number): Vec3Tuple {
  return [
    a[0] + (b[0] - a[0]) * t,
    a[1] + (b[1] - a[1]) * t,
    a[2] + (b[2] - a[2]) * t,
  ];
}

/**
 * Reflect vector `v` about `normal`.
 * Assumes `normal` is unit-length.
 */
export function reflect(v: Vec3Tuple, normal: Vec3Tuple): Vec3Tuple {
  const d = dot(v, normal);
  return [
    v[0] - 2 * d * normal[0],
    v[1] - 2 * d * normal[1],
    v[2] - 2 * d * normal[2],
  ];
}

// ---------------------------------------------------------------------------
// Products
// ---------------------------------------------------------------------------

/** Dot product. */
export function dot(a: Vec3Tuple, b: Vec3Tuple): number {
  return a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
}

/** Cross product. */
export function cross(a: Vec3Tuple, b: Vec3Tuple): Vec3Tuple {
  return [
    a[1] * b[2] - a[2] * b[1],
    a[2] * b[0] - a[0] * b[2],
    a[0] * b[1] - a[1] * b[0],
  ];
}

/** Angle in radians between two vectors. Returns 0 if either is zero-length. */
export function angle(a: Vec3Tuple, b: Vec3Tuple): number {
  const lenA = Math.sqrt(a[0] * a[0] + a[1] * a[1] + a[2] * a[2]);
  const lenB = Math.sqrt(b[0] * b[0] + b[1] * b[1] + b[2] * b[2]);
  if (lenA === 0 || lenB === 0) return 0;
  const cosAngle = Math.max(-1, Math.min(1, dot(a, b) / (lenA * lenB)));
  return Math.acos(cosAngle);
}

// ---------------------------------------------------------------------------
// Utility
// ---------------------------------------------------------------------------

/** Check strict equality of two vectors. */
export function equals(a: Vec3Tuple, b: Vec3Tuple): boolean {
  return a[0] === b[0] && a[1] === b[1] && a[2] === b[2];
}

/** Check approximate equality within an epsilon. */
export function approxEquals(a: Vec3Tuple, b: Vec3Tuple, eps = 1e-6): boolean {
  return (
    Math.abs(a[0] - b[0]) < eps &&
    Math.abs(a[1] - b[1]) < eps &&
    Math.abs(a[2] - b[2]) < eps
  );
}

/**
 * Clamp each component of `v` to the range [min, max].
 */
export function clamp(v: Vec3Tuple, min: number, max: number): Vec3Tuple {
  return [
    Math.max(min, Math.min(max, v[0])),
    Math.max(min, Math.min(max, v[1])),
    Math.max(min, Math.min(max, v[2])),
  ];
}

/**
 * Project vector `a` onto vector `b`.
 */
export function project(a: Vec3Tuple, b: Vec3Tuple): Vec3Tuple {
  const lenSqB = lengthSq(b);
  if (lenSqB === 0) return [0, 0, 0];
  const scalar = dot(a, b) / lenSqB;
  return scale(b, scalar);
}

/**
 * Returns a string representation for debugging.
 */
export function toString(v: Vec3Tuple, precision = 4): string {
  return `(${v[0].toFixed(precision)}, ${v[1].toFixed(precision)}, ${v[2].toFixed(precision)})`;
}

